WORD = re.compile(r"[a-z0-9']+")
def stats(text):
    words = WORD.findall(text.lower())
    n = len(words)
    if n == 0: return (0, 0.0, 1.0, 1.0)
    counts = Counter(words)
    bigrams = Counter(zip(words, words[1:]))
    return (n, len(counts)/n, counts.most_common(1)[0][1]/n,
            bigrams.most_common(1)[0][1]/max(n-1,1) if bigrams else 0.0)

